const item = $input.item.json;
const mall_id = item.mall_id;
const cmc_manager = item.cmc_manager;

// 현재 날짜
const now = new Date();
const calc_date = now.toISOString().split('T')[0];

// 2025년 2월부터 7월까지의 시작일과 종료일
const months = [
  { month: '2025-02', start: '2025-02-01', end: '2025-02-28' },
  { month: '2025-03', start: '2025-03-01', end: '2025-03-31' },
  { month: '2025-04', start: '2025-04-01', end: '2025-04-30' },
  { month: '2025-05', start: '2025-05-01', end: '2025-05-31' },
  { month: '2025-06', start: '2025-06-01', end: '2025-06-30' },
  { month: '2025-07', start: '2025-07-01', end: '2025-07-31' }
];

// 각 월별로 데이터 요청
const requests = months.map(m => ({
  json: {
    mall_id,
    cmc_manager,
    calc_date,
    month: m.month,
    startDate: m.start,
    endDate: m.end
  }
}));

return requests;

const item = $input.item.json;
const mall_id = item.mall_id;
const cmc_manager = item.cmc_manager;
const calc_date = item.calc_date;
const month = item.month;

// ClickHouse 쿼리 결과에서 매출 데이터 추출
let monthly_sales = 0;
if ($input.item.json.data && $input.item.json.data.length > 0) {
  const salesData = $input.item.json.data.find(row => row.month === month);
  if (salesData) {
    monthly_sales = salesData.sum_sal || 0;
  }
}

return [{
  json: {
    mall_id,
    cmc_manager,
    calc_date,
    month,
    monthly_sales
  }
}];

const salesData = $input.all();
const firstItem = salesData[0];
const mall_id = firstItem.json.mall_id;
const cmc_manager = firstItem.json.cmc_manager;
const calc_date = firstItem.json.calc_date;

// 월별 매출 데이터 정리
const monthlyData = {};
salesData.forEach(item => {
  monthlyData[item.json.month] = item.json.monthly_sales || 0;
});

// 평균 계산
const prev_3_months = ['2025-02', '2025-03', '2025-04'];
const recent_3_months = ['2025-05', '2025-06', '2025-07'];

const avg_sum_90_prev = prev_3_months.reduce((sum, month) => sum + (monthlyData[month] || 0), 0) / 3;
const avg_sum_90_recent = recent_3_months.reduce((sum, month) => sum + (monthlyData[month] || 0), 0) / 3;

// zScore_Raw 형식에 맞춰 데이터 구성
const result = {
  calc_date,
  mall_id,
  cmc_manager,
  cmc_manager_name: cmc_manager, // 임시로 동일하게 설정
  pg_join_date: '', // 패스
  pg_recency_days: 0, // 패스
  '2025-02': monthlyData['2025-02'] || 0,
  '2025-03': monthlyData['2025-03'] || 0,
  '2025-04': monthlyData['2025-04'] || 0,
  '2025-05': monthlyData['2025-05'] || 0,
  '2025-06': monthlyData['2025-06'] || 0,
  '2025-07': monthlyData['2025-07'] || 0,
  avg_sum_90_prev,
  avg_sum_90_recent,
  '2025-06': monthlyData['2025-06'] || 0, // 이전 30일
  '2025-07': monthlyData['2025-07'] || 0, // 최근 30일
  sfdc_has_history: false, // 패스
  sfdc_gap_flag: 0, // 패스
  ad_script_detect: 0, // 패스
  fetch_status: 200,
  fetch_error: '',
  updated_at: new Date().toISOString().replace('T', ' ').substring(0, 19)
};

return [{ json: result }];
